INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('su-90-iron-forge', 1, 'Heavy Ion Turret', '5D6 M.D. per blast', 1, '1,000 feet (305 m)', 'Each shot uses one melee attack (printed as each burst; the gun fires single shots).', 'Effectively unlimited.', NULL, 'A short-range ion cannon set just above the pilot''s compartment and fired by the pilot. Defense, then anti-personnel.'),
  ('su-90-iron-forge', 2, 'Dual Rail Gun Turrets (4)', '4D6 M.D. per 20 round burst from one barrel, or 1D4x10 M.D. per 40 round burst from both barrels', 1, '4,000 feet (1,219 m)', 'Bursts only.', '4,000 rounds per turret: 100 double-barrel bursts or 200 single-barrel bursts.', NULL, 'Heavy turrets, two above the pilot compartment and two at the back beneath the loading platform. Defense, then assault.'),
  ('su-90-iron-forge', 3, 'Large Crane Pry Bars/Jaws of Life (2)', '3D6+6 M.D. when spreading an opening or tearing through wreckage, armor or ruined cyborg bodies; Robotic pry/tear strength 50. It cannot punch.', 1, 'Touch/close combat', NULL, 'Effectively unlimited.', NULL, 'One on each large crane arm: twin tong-like bars that close together at rest, looking like a single bar, and spread apart to force hatches and doors, widen holes in hulls and walls, shift rubble and free trapped people. The operator can work them gently enough to lift the injured. Rescue tool, then forced entry.'),
  ('su-90-iron-forge', 4, 'Large Crane Laser Torches (2)', 'Settings of 3D6 S.D.C., 5D6 S.D.C., 1D6x10 S.D.C., 1 M.D., 1D4 M.D. and 2D4 M.D.', 1, '30 feet (9.1 m)', 'Each blast uses one melee attack.', 'Effectively unlimited.', NULL, 'A precision cutter on each large crane for slicing debris, removing bionic parts and armor, and welding repairs. Cutting and rescue, then defense.'),
  ('sn-247-torrent', 1, 'Rail Gun Turrets (2)', '1D4x10 M.D. per 20 round burst from each turret, or 2D4x10 M.D. when both turrets fire on one target together. No single shots.', 1, '4,000 feet (1,219 m)', 'A single burst, or a paired burst at one target, uses one melee attack.', 'A 4,000 round internal magazine per turret: 200 bursts each. The weapons locker holds another 4,000 rounds per gun.', NULL, 'Two heavy turrets toward the bow, each turning 200 degrees with a 100 degree vertical arc, so they cover the sides, the front and the air. They work separately or linked onto one target under one gunner or crew member. Assault, then anti-armor.'),
  ('sn-247-torrent', 2, 'Rear Dual Ion Turret', '4D6 M.D. per single blast, or 1D4x10 M.D. per double blast', 1, '2,000 feet (610 m)', 'Each single or double blast uses one of the gunner''s melee attacks.', 'Effectively unlimited.', '+1 to strike when worked by a gunner; no one else gets it.', 'A short-range ion turret at the stern for knocking down missile volleys and hitting pursuing vehicles and sea monsters. It swings 90 degrees up and down and side to side. Defense, then anti-missile.'),
  ('sn-247-torrent', 3, 'Mini-Missile Launcher', 'Varies with the missile; usually high explosive (5D6 M.D. to a 5 foot/1.5 m radius) or fragmentation (5D6 M.D. to a 20 foot/6.1 m radius)', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 4 or 8.', '8, plus 32 spares for reloads. One trained crew member reloads it in 1D4+1 minutes; twice that for someone inexperienced.', NULL, 'A turret atop the crew cabin, aimed at incoming flyers, seaborne threats, missile volleys and the odd sea monster, and for enemy boats and shore positions. Assault and defense, then anti-fortification.'),
  ('sn-247-torrent', 4, 'Medium Torpedo Launchers (2)', 'Any medium torpedo; the standard high explosive torpedo does 3D4x10 M.D.', 1, 'Five miles (8 km)', 'One at a time or volleys of two.', '8 torpedoes, four per tube.', NULL, 'One tube on each side near the bow, below the waterline; the gunboat''s main answer to light submarines, underwater cyborgs, sea serpents and big ships. Anti-ship, then anti-monster.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 machines are in' AS assertion, count(*) AS got, 2 AS want
  FROM vehicles WHERE slug IN ('su-90-iron-forge', 'sn-247-torrent');
SELECT 'their 25 locations are in' AS assertion, count(*) AS got, 25 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('su-90-iron-forge', 'sn-247-torrent');
SELECT 'their 8 weapon entries are in' AS assertion, count(*) AS got, 8 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('su-90-iron-forge', 'sn-247-torrent');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('su-90-iron-forge', 'sn-247-torrent') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

